import { readFile, writeFile } from 'node:fs/promises';
const html = await readFile(new URL('../src/admin.html', import.meta.url), 'utf8');
await writeFile(new URL('../src/admin.generated.ts', import.meta.url),
  '// Generated by scripts/inline-admin.mjs. Edit admin.html instead.\nexport default ' + JSON.stringify(html) + ';\n');
